mapper.select:
select count(isd.sku_id) from init_stock_detail isd
inner join init_stock ism on ism.id = isd.main_id and ism.is_deleted = false
where isd.sku_id = #{skuId} and ism.warehouse_id = #{warehouseId} and isd.warehouse_location = #{warehouseLocation}
and ism.invalid_status = false

    and isd.main_id != #{id}
